{
  "tool_name": "roles",
  "class": "environment_static",
  "observation": {
    "role_details": {
      "name": "Investigator",
      "faction": "Town",
      "alignment": "Town Investigative",
      "abilities": [
        "Investigate one person each night for a clue to their role."
      ],
      "mechanics": {
        "clues": "You receive an investigative result that could match one of several roles. Each result is a vague description or grouping of roles.",
        "result_groups": [
          "For example, you might see \"Your target could be a Bodyguard, Godfather, or Arsonist\" (depending on target's role).",
          "The Coven Expansion uses fixed result groupings for roles; Framed or Hexed targets will show the Framer/Hex Master grouping."
        ]
      },
      "notifications": [
        "You will receive a message each night with your investigation result for the target.",
        "If your target was framed or hexed, your result may correspond to the Framer/Hex Master instead of the target's real alignment."
      ],
      "win_condition": "Lynch every criminal and evildoer.",
      "wins_with": [
        "Town",
        "Survivor"
      ],
      "notes": null,
      "immunities": null,
      "visit_type": "Non-Harmful"
    }
  }
}

