    "role_details": {
      "name": "Amnesiac",
      "faction": "Neutral",
      "alignment": "Neutral Benign",
      "abilities": [
        "Remember who you were by choosing a role from the graveyard."
      ],
      "mechanics": {
        "remember": "At night, if there are dead roles in the graveyard, you may choose one of them to \"remember\". You will then change into that role on the next day, effectively becoming that role (with its abilities and win condition).",
        "limitation": "You can only successfully remember once. If you do, you adopt the alignment and objectives of the new role going forward."
      },
      "notifications": [
        "Upon remembering, all players see a message like \"An Amnesiac has remembered they were [Role]!\" revealing your new role.",
        "If you attempt to remember a role but are role-blocked or otherwise prevented, it fails and you can try again another night."
      ],
      "win_condition": "Initially, you have no win condition until you remember a role. After remembering, you adopt that role's win condition.",
      "wins_with": null,
      "notes": [
        "If you remember a role that had a unique condition (like a unique role when one already exists alive), it might not be allowed depending on the game (some games restrict remembering unique roles if one is still alive)."
      ],
      "immunities": null,
      "visit_type": "Astral"
    }
  }
}

