    }
  }
}

{
  "tool_name": "roles",
  "class": "environment_static",
  "observation": {
    "role_details": {
      "name": "Bodyguard",
      "faction": "Town",
      "alignment": "Town Protective",
      "abilities": [
        "Protect one player each night from attacks (counterattacks attackers).",
        "Use a bulletproof vest on self once per game."
      ],
      "mechanics": {
        "protection": "Can protect a target from one attack each night, counterattacking the attacker. Both Bodyguard and attacker suffer a Powerful Attack.",
        "vest": "If targeting self, consumes vest, grants Basic Defense for the night. Vest does not counterattack.",
        "multiple_attackers": "If multiple killers attack the protected target, Bodyguard kills one attacker and dies; others can still attack.",
        "exceptions": [
          "Cannot protect from Jailor executions, Veteran alerts, Ambusher, Medusa (Stone Gaze at home), Hex Master (Hex Bomb), Arsonists (Ignition), Jesters (Haunt).",
          "Cannot save another Bodyguard who dies in a counterattack.",
          "Some attacks (e.g., Pestilence or Juggernaut with Powerful Attack) may kill the Bodyguard and/or the protected target."
        ]
      },
      "notifications": [
        "If you die protecting someone, your cause of death will state that you \"died guarding someone.\"",
        "An attacker killed by a Bodyguard will see that they \"were killed by a Bodyguard.\"",
        "Certain roles (Necromancer's ghoul, Pirate duel, Serial Killer, etc.) have unique interactions with Bodyguard protection."
      ],
      "win_condition": "Lynch every criminal and evildoer.",
      "wins_with": [
        "Town",
        "Survivor"
      ],
      "notes": [
        "Cannot be a Lover or VIP in related game modes.",
        "If multiple Bodyguards protect the same target, each will counterattack a different attacker."
      ],
      "immunities": null,
      "visit_type": "Astral"
    }
  }
}

